contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    fallback(bytes calldata) external payable returns (bytes memory) {
        bytes4 sig = bytes4(msg.data);
        if (sig == 0x70a08231) { // balanceOf(address)
            return abi.encode(uint256(10**18));
        }
        return "";
    }

    function testMintBurn(uint256 amount, uint256 burnAmount) external {
        require(amount > 0, "!amount");
        require(burnAmount > 0 && burnAmount <= amount, "!burn");

        // Act as a (curated) pool: mint synths for ourselves.
        c.mintSynth(address(this), amount);

        // Send the minted synths back into the synth contract.
        c.transfer(address(c), burnAmount);

        uint256 supplyBefore = c.totalSupply();

        // Burn the synths held by the contract.
        c.burnSynth();

        // In P the recorded LP collateral makes _amountUnits > 0, so the
        // held synths are actually burned and totalSupply decreases.
        // In M the LP collateral is never recorded, so nothing is burned
        // and totalSupply stays unchanged.
        assert(c.totalSupply() == supplyBefore - burnAmount);
    }
}
